insert into soal (kategori,pertanyaan,pilihan,jawaban,penjelasan,urutan,bab,sumber_pdf,halaman,kalimat,kalimat_ruby,kosakata) values
('宿泊分野','レストラン接客の基本にある精神はどれですか？','["おもてなし", "値引き", "スピード", "効率"]'::jsonb,0,'日本人が大切にしてきた「おもてなし」の精神が基本です。',401,'04 · レストランサービス','2号',44,'これは 日本人が大切にしてきた精神で、接客サービスの基本となります。 なお、「おもてなし」は英語のホスピタリティ(Hospitality) と同意語となります。 ホテル・旅館での食事は、滞在されるお客様にとっての楽しみの一つであり、お 客様に「おもてなし」を伝えるため',null,'[]'::jsonb),
('宿泊分野','食事サービスで身につけるべきものはどれですか？','["基本動作・ルール・マナー", "会計処理", "予約管理", "清掃計画"]'::jsonb,0,'基本動作・ルール・マナーを身につけることが大切です。',402,'04 · レストランサービス','2号',44,'ホテル・旅館での食事は、滞在されるお客様にとっての楽しみの一つであり、お 客様に「おもてなし」を伝えるためには、基本動作・決められたルールやマナー を身に着けることが大切です。また、レストランにおいてお客様に満足いただく ために、責任者（マネージャーや店長）には、料理、サービス、衛生管理、お客 様対応、クレーム対応などの全体的な責任者としての行動や知識とともに、従業 員',null,'[]'::jsonb),
('宿泊分野','レストランでのあいさつの意味はどれですか？','["歓迎を伝え第一印象を決める", "売上を記録する", "席を決める", "料理を運ぶ"]'::jsonb,0,'あいさつは歓迎の気持ちと第一印象を決めます。',403,'04 · レストランサービス','2号',45,'お 客様に歓迎の気持ちを伝えるとともに、お客様の第一印象を決める大切な意味を持ちます。 相手によい印象をあたえるあいさつのポイントは以下のとおりです。 また、レストランで接客する際には、表情もとても大切な要素です。',null,'[]'::jsonb),
('宿泊分野','レストラン接客で、あいさつ以外に大切な要素はどれですか？','["表情", "服装のブランド", "声の大きさだけ", "速さ"]'::jsonb,0,'表情もとても大切な要素です。',404,'04 · レストランサービス','2号',45,'また、レストランで接客する際には、表情もとても大切な要素です。笑顔を意識することで、 お客様の印象も良くなります。大切なポイントは以下のとおりです。 1.サービスの基本動作 ・相手の目を見て、元気ではっきりとした声であいさつをすること ・お客様を見かけたら、自分から積極的にあいさつをすること',null,'[]'::jsonb),
('宿泊分野','接客中に心がけることはどれですか？','["お客様の変化に気づき先回りする", "自分の作業を優先する", "話しかけない", "席を離れない"]'::jsonb,0,'わずかな変化からリクエストに気づき対応します。',405,'04 · レストランサービス','2号',45,'また、レストランでの接客中は、常にお客様に気を配り、わずかな変化や動きからお客様 のリクエストに気づき、適切な対応をすることが大切です。 例えば、食べ終わったお皿を下げる、水やワインをつぎ足す、追加のドリンクやフードの オーダーをお伺いする、フォークやナイフを落としたら速やかに新しいものを用意する、 など状況に',null,'[]'::jsonb),
('宿泊分野','サポートが必要なお客様の例として正しいのはどれですか？','["車いす・妊娠中・高齢・障害・宗教上の事情", "予約なしの客", "常連客", "団体客"]'::jsonb,0,'車いす・妊娠中・高齢・障害・宗教など様々な事情があります。',406,'04 · レストランサービス','2号',47,'①配慮が必要なお客様 車いすを使用している、妊娠中である、高齢である、障害をお持ちである、宗教上の事 情がある、など様々な要因でサポートが必要なお客様がいます。お客様に寄り添い、そ れぞれの事情に配慮した接客対応を心がることが必要です。',null,'[]'::jsonb),
('宿泊分野','サポートする前にすべきことはどれですか？','["必要を丁寧に確認してから行動する", "すぐ抱きかかえる", "自己判断で動かす", "断る"]'::jsonb,0,'どのようなサポートが必要か確認してから行動します。',407,'04 · レストランサービス','2号',47,'サポートする際には、どの ようなサポートが必要か、お客様と丁寧なコミュニケーションを取って確かめてから行 動します。 また、配慮が必要なお客様が来られた際にはどのテーブルに案内することが適切か、な ど事前に確認して準備しておくことが大切です。',null,'[]'::jsonb),
('宿泊分野','予約客の席の割り当てを何といいますか？','["テーブルアサイン", "アップセル", "ブッキング", "アサインシート"]'::jsonb,0,'席の割り当てをテーブルアサインといいます。',408,'04 · レストランサービス','2号',47,'事前に予約客の情報を確認して、適切 なテーブルアサイン（予約客のテーブルの割り当て）を行うようにします。例えば、足 が不自由なお客様が来られた際は、お客様のリクエストを確認したうえで、出入り口の 近くや広いスペースを案内するなど、状況に応じて適切な席に案内し、お客様の着席を 補助する場合は、音をた',null,'[]'::jsonb),
('宿泊分野','クレームへの対応で大切なことはどれですか？','["正しい手順で速やかに対応する", "無視する", "言い返す", "後回しにする"]'::jsonb,0,'決められた手順で速やかに対応します。',409,'04 · レストランサービス','2号',47,'クレームに対しては、以下の通り、正しい手順で速やかに対応すること が大切です。 ・まずは丁寧におわびし、その後、速やかに適切な処置をする ・どんなに小さな問題でも、自身で判断せずに必ず上司に報告して対応する ・お客様の言い分や苦情の内容、問題点をしっかりと聞く 3.お客様対応 レストランの責',null,'[]'::jsonb),
('宿泊分野','クレーム対応で心がけることはどれですか？','["お客様を理解する気持ちを持つ", "責任を回避する", "料金を下げる", "上司に任せる"]'::jsonb,0,'理解する気持ち・意思の確認・柔軟な対応・尊重が大切です。',410,'04 · レストランサービス','2号',47,'様の特性やニーズを理解し、適切な準備や対応をして、 お客様に満足いただき、お客様と良好な関係性をつくることが求められます。 具体的には、 ・お客様を理解する気持ちを持つ ・お客様の意思やリクエストを確認する ・お客様に寄り添い、柔軟な対応を心がける ・お客様のことを尊重する ことなどに気を付けて行動することが重要です。',null,'[]'::jsonb),
('宿泊分野','料理を提供するときの向きはどれですか？','["お客様から見て正面にくるように", "自分から見て正面", "横向き", "向きは自由"]'::jsonb,0,'お客様から見て正面になるように提供します。',411,'04 · レストランサービス','2号',48,'また、お料理の正しい向きを確認 して、必ずお客様から見て、お料理が正面にくるように提供します。洋食では、基本的に はお料理は左側から提供します。お飲み物は右側から提供します。 また、ドリンクの提供時にグラスを持つ際は、コップの半分よりも下を持つようにします。',null,'[]'::jsonb),
('宿泊分野','レストランでの提案で大切なことはどれですか？','["好みやニーズに合わせ適切なタイミングで提案する", "すぐ勧める", "何も提案しない", "高額だけ勧める"]'::jsonb,0,'お客様の好みに合わせ、適切なタイミングで提案します。',412,'04 · レストランサービス','2号',48,'レストランでは、お客様と丁寧なコミュニケーションを取り、お客様の好みやニーズに合 わせたメニューを適切なタイミングで提案することが大切です。特に、食事メニューに合 わせたドリンクを提供することで、お客様満足度を向上させることができるとともに、よ り高価なドリンクを注文してもらうことが期待できます。',null,'[]'::jsonb),
('宿泊分野','和食の基本とされる言葉はどれですか？','["一汁三菜", "ワンプレート", "コース仕立て", "ビュッフェ形式"]'::jsonb,0,'和食の基本は「一汁三菜」です。',413,'04 · レストランサービス','2号',49,'また和食の基本として「一 汁三菜」という言葉があります。ご飯・汁・3 つの菜（お かず）を組み合わせた献立です。一般的には、左側に ご飯、右側に汁、左奥に副菜、右奥に主菜を置きます。',null,'[]'::jsonb),
('宿泊分野','和食の基本的な提供順序の最初はどれですか？','["前菜", "ごはん", "水菓子", "焼き物"]'::jsonb,0,'和食は前菜→お造り→椀盛…の順です。',414,'04 · レストランサービス','2号',50,'旅館で出てくる懐石料理は、一汁三菜を基本にしたメニュー構成となっており、 りょかん かいせきりょうり いちじゅうさんさい きほん こうせい で',null,'[]'::jsonb),
('宿泊分野','肉や魚を保存・解凍するときに気をつけることはどれですか？','["ドリップが出ないようにする", "常温で放置する", "水に浸す", "二度解凍する"]'::jsonb,0,'ドリップが出ないよう保存・解凍を工夫します。',415,'04 · レストランサービス','2号',54,'特にノロウイルスは非常に強い感染力を持ち、毎年11 ～2 月の冬場にかけて 多くの患者が発生します。 また、肉や魚はドリップ（赤い液体）が出ないように保存方法や解凍方法を工夫すること が重要です。',null,'[]'::jsonb),
('宿泊分野','食材や飲料のコストを管理する手法はどれですか？','["F&Bコントロール", "ABC分析", "ADR", "RevPAR"]'::jsonb,0,'F&Bコントロールは食品・飲料のコスト管理です。',416,'04 · レストランサービス','2号',55,'一般的には30% を目標 と設定して原価コントロールを行います。 ②F＆B コントロール（食品および飲料管理） 食材や飲料のコストを適切に管理する方法です。具体的には、食材の原材料や飲み物の 品質、仕入れの量や価格をチェックして管理します。',null,'[]'::jsonb),
('宿泊分野','メニューを売上や利益率でランク分けする手法はどれですか？','["ABC分析", "F&Bコントロール", "ダイナミックプライシング", "セグメンテーション"]'::jsonb,0,'ABC分析はメニューをランク分けして管理します。',417,'04 · レストランサービス','2号',55,'さらに、売上データを分析したり、 在庫を適切に管理したり、食品ロスを減らしたりすることで、毎日のコストを効率的に 管理します。 ③ABC 分析（売上分析手法） メニューごとに売上や利益率を基にランク分けして管理する方法です。',null,'[]'::jsonb),
('宿泊分野','災害が起きたときに求められる対応はどれですか？','["冷静・迅速に対応する", "パニックになる", "報告を待つ", "客室に戻る"]'::jsonb,0,'冷静かつ迅速な対応が求められます。',418,'05 · 安全衛生管理・その他','2号',58,'旅館、ホテルにおいて想定されるリスクを理解し、日常業務の 中で常にその回避、防止を図るとともに、火災や地震などの災 害が生じた万一の際に冷静・迅速に対応できるようにしておく ことが重要です。',null,'[]'::jsonb),
('宿泊分野','緊急事態に備えて日頃から行うことはどれですか？','["訓練とシミュレーション", "何もしない", "記録だけ取る", "器具を隠す"]'::jsonb,0,'日常から訓練し、場面を想定して備えます。',419,'05 · 安全衛生管理・その他','2号',59,'ですから、常にそのような緊急事態に対応 できるよう、日常から訓練を行うとともに、想定されるリスクを理解し自らの業務におけ る具体的な場面での対応をシミュレーションしておく必要があります。',null,'[]'::jsonb),
('宿泊分野（1号）','お客様が最初に体験する対応はどれですか？','["チェックイン", "チェックアウト", "朝食", "清掃"]'::jsonb,0,'チェックインはお客様が最初に体験する対応です。',420,'1号 · 01 · フロント業務','1号',11,'そのため、 お客様に良いイメージを与えられるように、清潔感がある身だしなみ、正しい姿勢、丁寧 な言葉づかい、で対応することが重要です。 などがあります。 また、日本人以外の外国人のお客様が日',null,'[]'::jsonb),
('宿泊分野（1号）','外国人のお客様が宿泊する際、法律で定められていることはどれですか？','["パスポートのコピーを取って保管する", "通訳を雇う", "現金のみ受け取る", "別館に案内する"]'::jsonb,0,'パスポートのコピー取得と保管が法律で定められています。',421,'1号 · 01 · フロント業務','1号',11,'また、日本人以外の外国人のお客様が日本の宿泊施設に泊まる場合は、パスポートのコピー をとって保管することが日本の法律で定められているので、忘れないようにお客様に提示 していただくよう気を付ける必要があります。',null,'[]'::jsonb),
('宿泊分野（1号）','チェックイン時刻の一般的な目安はどれですか？','["14時または15時", "10時", "18時", "12時"]'::jsonb,0,'チェックインは14〜15時、チェックアウトは10〜11時が多いです。',422,'1号 · 01 · フロント業務','1号',12,'なお、チェックイン、 チェックアウト時間は個々の宿泊施設により異なりますが、チェックインは14 時または 15 時、チェックアウトは10 時または11 時である場合が多くなっています。',null,'[]'::jsonb),
('宿泊分野（1号）','チェックアウト時刻の一般的な目安はどれですか？','["10時または11時", "14時", "8時", "16時"]'::jsonb,0,'チェックアウトは10〜11時が多くなっています。',423,'1号 · 01 · フロント業務','1号',12,'なお、チェックイン、 チェックアウト時間は個々の宿泊施設により異なりますが、チェックインは14 時または 15 時、チェックアウトは10 時または11 時である場合が多くなっています。',null,'[]'::jsonb),
('宿泊分野（1号）','客室が利用できる時間の範囲はどれですか？','["チェックインからチェックアウトまで", "24時間いつでも", "夕方から朝まで", "正午から正午まで"]'::jsonb,0,'利用時間はチェックイン〜チェックアウトの範囲です。',424,'1号 · 01 · フロント業務','1号',12,'きる場所への行き方や利 用可能な時間、さらには、火災や自然災害時に利用する非常口と避難経路などを丁寧に説 明する必要があります。多くの場合、お泊りになるお部屋の利用可能な時間は宿泊施設が 定めたチェックインからチェックアウト時間の範囲内となります。',null,'[]'::jsonb),
('宿泊分野（1号）','フロントで問い合わせに対応するために必要なことはどれですか？','["館内外の幅広い知識", "料理の技術", "経理の資格", "運転免許"]'::jsonb,0,'館内や近隣店舗など幅広い知識が必要です。',425,'1号 · 01 · フロント業務','1号',13,'はもちろん、近くのお店など館外のことについてもフロントに問い合わせが入ること も多くありますので、お客様からのリクエストに対応できるように、幅広い知識を身につ けておくことが重要です。',null,'[]'::jsonb),
('宿泊分野（1号）','フロントが把握しておくべきことはどれですか？','["他部門の作業内容", "他社の売上", "地域の人口", "天気予報"]'::jsonb,0,'他部門の作業を理解しておく必要があります。',426,'1号 · 01 · フロント業務','1号',13,'また、お部屋や館内の設備の準備ができているか、きちんと正しい場所にスタッフが配置 されているかなどの情報を知っておくためには、フロント以外の部門がどのような作業を しているかを正しく理解しておく必要もあります。',null,'[]'::jsonb),
('宿泊分野（1号）','チェックアウト時に確認するものはどれですか？','["館内利用の有無と内容", "翌日の予約", "シフト", "仕入れ"]'::jsonb,0,'館内利用の有無と内容を確認して精算します。',427,'1号 · 01 · フロント業務','1号',17,'お客様がご宿泊以外の館内でご利用したサービス（プランには含まれていない飲料、ルー ムサービス、マッサージなど）を「館内利用」といいます。館内利用の有無とその内容を お客様のチェックアウトの際に確認します。',null,'[]'::jsonb),
('宿泊分野（1号）','会計で気をつけることはどれですか？','["請求金額の間違いがないようにする", "端数を切り上げる", "現金のみ扱う", "領収書を出さない"]'::jsonb,0,'支払い方法が複数あるため、金額の誤りに注意します。',428,'1号 · 01 · フロント業務','1号',17,'お支払いの方法がいくつかあり、請求金額の間違いなどがないよう気をつける 必要があります。 なお、日本では習慣としてチップを受け取る文化はありませんが、サービス料を宿泊料金 に含んで請求する場合と別に請求する場合があります。',null,'[]'::jsonb),
('宿泊分野（1号）','電話を切るときの正しい順番はどれですか？','["お客様が切ってから切る", "先に切る", "切らずに放置", "同僚に任せる"]'::jsonb,0,'お客様が切ってから切ります。',429,'1号 · 01 · フロント業務','1号',14,'また、お客様との電話を切る際には、必ず、 お客様が電話を切ってから電話を切るようにします。 また、ご滞在中のお客様から料理や飲み物をお部屋に届けるルームサービスの注文を電話 で受ける場合は、ご注文内容に間違いがないかご注文内容を繰り返すなどして、しっかり 確認することが重要です。',null,'[]'::jsonb),
('宿泊分野（1号）','ルームサービスの注文を受けるとき、間違いを防ぐ方法はどれですか？','["注文内容を繰り返して確認する", "メモを取らない", "早く切る", "厨房に直接つなぐ"]'::jsonb,0,'注文内容を復唱して確認します。',430,'1号 · 01 · フロント業務','1号',14,'また、ご滞在中のお客様から料理や飲み物をお部屋に届けるルームサービスの注文を電話 で受ける場合は、ご注文内容に間違いがないかご注文内容を繰り返すなどして、しっかり 確認することが重要です。',null,'[]'::jsonb),
('宿泊分野（1号）','客室に入るときの正しい手順はどれですか？','["ノックか呼び鈴の後、許可をもらう", "合鍵で入る", "静かに開ける", "清掃中なら自由に入る"]'::jsonb,0,'必ずノック・呼び鈴をし、許可を得てから入室します。',431,'1号 · 01 · フロント業務','1号',15,'らのリクエストに応じて、アメニティのお届け、ルームサービスなど、お客様が 宿泊している客室に入ることが必要なことがあります。その際には、必ずドアをノックす るか呼び鈴を鳴らし、お客様が「入ってください」という許可をもらってから客室に入ら なければいけません。',null,'[]'::jsonb),
('宿泊分野（1号）','接客の基本として正しいのはどれですか？','["あいさつ", "会計", "予約", "清掃"]'::jsonb,0,'あいさつは接客の基本です。',432,'1号 · 03 · 接客','1号',28,'接客について 1.あいさつ 2.接客の基本姿勢とおじぎ 3.接客の際の話し方 4.具体的な接客方法 5.電話対応 6.クレーム（苦情）対応 あいさつは接客の基本です。お客様にあいさつをすると、お客様は気持ちよく滞在す ることができます。',null,'[]'::jsonb),
('宿泊分野（1号）','あいさつで大切なことはどれですか？','["よい印象を与える", "声を小さくする", "目をそらす", "無言で頭を下げる"]'::jsonb,0,'よい印象を与えるあいさつが大切です。',433,'1号 · 03 · 接客','1号',37,'お 客様に歓迎の気持ちを伝えるとともに、お客様の第一印象を決める大切な意味を持ちます。 相手によい印象をあたえるあいさつのポイントは以下のとおりです。 また、レストランで接客する際には、表情もとても大切な要素です。',null,'[]'::jsonb),
('宿泊分野（1号）','レストラン接客であいさつ以外に大切なものはどれですか？','["表情", "靴の色", "身長", "血液型"]'::jsonb,0,'表情もとても大切な要素です。',434,'1号 · 03 · 接客','1号',37,'また、レストランで接客する際には、表情もとても大切な要素です。笑顔を意識することで、 お客様の印象も良くなります。大切なポイントは以下のとおりです。 1.サービスの基本動作 ・相手の目を見て、元気ではっきりとした声であいさつをすること ・お客様を見かけたら、自分から積極的にあいさつをすること',null,'[]'::jsonb),
('宿泊分野（1号）','料理を運ぶときに注意することはどれですか？','["お皿の持ち方", "歩く速さだけ", "声の大きさ", "会計の順番"]'::jsonb,0,'お皿の持ち方に注意が必要です。',435,'1号 · 04 · レストランサービス','1号',39,'親指が料理に ついたり、お皿に指紋がつかないように気を付けます。また、お料理の正しい向きを確認 して、必ずお客様から見て、お料理が正面にくるように提供します。洋食では、基本的に はお料理は左側から提供します。',null,'[]'::jsonb),
('宿泊分野（1号）','料理を出す向きで正しいのはどれですか？','["お客様から見て正面", "自分から見て正面", "必ず横向き", "決まりはない"]'::jsonb,0,'お客様から見て正面にくるように出します。',436,'1号 · 04 · レストランサービス','1号',39,'また、お料理の正しい向きを確認 して、必ずお客様から見て、お料理が正面にくるように提供します。洋食では、基本的に はお料理は左側から提供します。お飲み物は右側から提供します。 また、ドリンクの提供時にグラスを持つ際は、コップの半分よりも下を持つようにします。',null,'[]'::jsonb),
('宿泊分野（1号）','和食の基本とされる考え方はどれですか？','["一汁三菜", "ワンプレート", "コース", "ビュッフェ"]'::jsonb,0,'和食の基本は一汁三菜です。',437,'1号 · 04 · レストランサービス','1号',40,'また和食の基本として「一 汁三菜」という言葉があります。ご飯・汁・3 つの菜（お かず）を組み合わせた献立です。一般的には、左側に ご飯、右側に汁、左奥に副菜、右奥に主菜を置きます。',null,'[]'::jsonb),
('宿泊分野（1号）','食物アレルギーの重い症状を何といいますか？','["アナフィラキシーショック", "ノーショー", "ドリップ", "デポジット"]'::jsonb,0,'アナフィラキシーショックは命に関わります。',438,'1号 · 04 · レストランサービス','1号',42,'症状がひどいときは、アナフィラキシーショックといい、 呼吸困難など重い症状が出て、適切な対応をしないと死にいたる場合があります。 一般的なアレルゲンとしては、卵・牛乳・ナッツ類・魚介類・小麦・大豆などが代表的です。',null,'[]'::jsonb),
('宿泊分野（1号）','アレルギー対応で必ず行うことはどれですか？','["有無を確認し情報を共有する", "お客様の判断に任せる", "加熱する", "何もしない"]'::jsonb,0,'必ず確認し、調理場・スタッフで共有します。',439,'1号 · 04 · レストランサービス','1号',42,'誤ってアレルギー反応が出る食材を食べないことが重要であり、予約時や来店時に、必ず アレルギーの有無をお客様に確認して、アレルギーがある場合は正確な情報を調理場やス タッフ内で共有します。',null,'[]'::jsonb),
('宿泊分野（1号）','レストランの安全衛生で大切なことはどれですか？','["適切な清掃作業", "装飾を増やす", "席を減らす", "音量を上げる"]'::jsonb,0,'適切な清掃が安全衛生の基本です。',440,'1号 · 04 · レストランサービス','1号',43,'具体的には、 などを行わなければいけません。 適切な清掃作業は、レストランの安全衛生管理のうえでとても大切です。こまめな 清掃を継続して、常に清潔な状態を維持することが求められます。',null,'[]'::jsonb),
('宿泊分野（1号）','災害時に求められる対応はどれですか？','["冷静・迅速に対応", "報告を待つ", "様子を見る", "記録を取る"]'::jsonb,0,'冷静かつ迅速に対応できるようにしておきます。',441,'1号 · 05 · 安全衛生管理','1号',46,'ホテルにおいて想定されるリスクを理解し、日常業務の中で常 にその回避、防止を図るとともに、 地震などの自然災害が生じた万一の際に冷静・迅速に対応でき るようにしておくことが重要です。',null,'[]'::jsonb),
('宿泊分野（1号）','緊急事態への備えとして正しいのはどれですか？','["日常から訓練する", "訓練は不要", "年に一度だけ", "担当者だけが行う"]'::jsonb,0,'日常から訓練し、場面を想定して備えます。',442,'1号 · 05 · 安全衛生管理','1号',47,'ですから、常にそのような緊急事態に対応 できるよう、日常から訓練を行うとともに、想定されるリスクを理解し自らの業務におけ る具体的な場面での対応をシミュレーションしておく必要があります。',null,'[]'::jsonb),
('宿泊分野（1号）','万一の災害時に確保すべきことはどれですか？','["お客様の安全", "売上", "備品", "予約数"]'::jsonb,0,'万一の際にもお客様の安全を確保できるようにします。',443,'1号 · 05 · 安全衛生管理','1号',48,'事故が起こらないよ う万全を尽くすことは当たり前ですが、万一、火災や自然災害等が生じた場合にもお客様 の安全を確保できるようにしておかなければいけません。 ・お客様の個人情報が流出することがないよう､お客様の情報 （氏名､住所などプライバシーに関する情報）の重要性を理解し､その取扱いに関して 外に漏らしたりすることなどないように細心の注意を払わなければ',null,'[]'::jsonb),
('宿泊分野（1号）','SDGsの観点から宿泊施設に求められることはどれですか？','["環境にやさしい取り組み", "使い捨ての増加", "水の大量使用", "冷暖房の最大化"]'::jsonb,0,'環境にやさしい取り組みが重要です。',444,'1号 · 05 · 安全衛生管理','1号',51,'5.環境対応について そのほか、SDGs の重要性が増していく中、宿泊施設において環境にやさしい取り組みを進 めていくことがとても重要です。具体的には、 ・節電、節水などの省エネルギーに努める ・紙の無駄使いをなくし、捨てる時は分別に努める ・環境リサイクルや資源の節減について上司や担当者に提案する ことなどをしっかりと行っていかなければい',null,'[]'::jsonb);
